{"path":"/workspace/source/packages/privacy/src/redact.ts","command":"create","file_text":"const PII_KEYS = new Set([
  'email',
  'name',
  'phone',
  'customerEmail',
  'billingName',
  'billingAddress',
  'billing_name',
  'billing_address',
  'line1',
  'line2',
  'city',
  'region',
  'postalCode',
  'postal_code',
  'externalReference',
  'external_reference',
]);

export function erasedCustomerRecord(customerId: string): Record<string, unknown> {
  return { id: customerId, status: 'erased' };
}

export function classifyErasureError(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error);
  if (message.includes('mailpit')) return 'notification_store_unavailable';
  if (message.includes('opensearch') || message.includes('index_not_found') || message.includes('search_')) {
    return 'search_index_unavailable';
  }
  if (message.includes('minio') || message.includes('S3') || message.includes('object')) {
    return 'object_store_unavailable';
  }
  if (message.includes('ECONNREFUSED') && message.includes('6379')) return 'cache_unavailable';
  if (message.includes('Redis') || message.includes('redis')) return 'cache_unavailable';
  return 'cleanup_failed';
}

/** Removes known personal-data keys from event and job payloads. */
export function redactPii(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((item) => redactPii(item));
  if (!value || typeof value !== 'object') return value;
  const source = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const [key, nested] of Object.entries(source)) {
    if (PII_KEYS.has(key)) continue;
    if (key === 'customer' && nested && typeof nested === 'object' && !Array.isArray(nested)) {
      const customer = nested as Record<string, unknown>;
      result[key] = erasedCustomerRecord(typeof customer.id === 'string' ? customer.id : typeof customer.customerId === 'string' ? customer.customerId : 'erased');
      continue;
    }
    if (key === 'customerSnapshot' || key === 'customer_snapshot' || key === 'billing_snapshot') {
      const snapshot = nested && typeof nested === 'object' && !Array.isArray(nested) ? nested as Record<string, unknown> : {};
      result[key] = erasedCustomerRecord(typeof snapshot.id === 'string' ? snapshot.id : 'erased');
      continue;
    }
    result[key] = redactPii(nested);
  }
  result.erased = true;
  return result;
}
"}

{"path":"/workspace/source/packages/operations/src/idempotency.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import type pg from 'pg';

export function requestHash(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

export async function reserveIdempotency(
  client: pg.PoolClient,
  merchantId: string,
  scope: string,
  key: string,
  hash: string,
): Promise<{ status: number; body: unknown } | undefined> {
  const inserted = await client.query(
    `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
     VALUES($1,$2,$3,$4,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
    [merchantId, scope, key, hash],
  );
  if (inserted.rowCount) return undefined;
  const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
    `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
     WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`, [merchantId, scope, key],
  );
  const row = existing.rows[0];
  if (!row || row.request_hash !== hash) throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
  if (row.response_status === null) throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
  return { status: row.response_status, body: row.response_body };
}

export async function completeIdempotency(
  client: pg.PoolClient, merchantId: string, scope: string, key: string, status: number, body: unknown,
): Promise<void> {
  await client.query(
    `UPDATE operations.idempotency_keys SET response_status=$4,response_body=$5
     WHERE merchant_id=$1 AND scope=$2 AND key=$3`, [merchantId, scope, key, status, body],
  );
}
"}

